import json,itertools
from datetime import date
from decimal import Decimal,ROUND_HALF_UP
d=json.loads(context)
qs={s:[] for s in d['skus']}
for q in d['quotes']:
 s=q['sku']
 if q['quality']=='approved' and date.fromisoformat(q['arrival'])<=date.fromisoformat(d['skus'][s]['deadline']) and d['skus'][s]['demand']<=q['units']<=d['skus'][s]['demand']+2: qs[s].append(q)
vs={v['id']:v for v in d['vendors']}
best=None
for sel in itertools.product(*(qs[s] for s in d['skus'])):
 by={}
 for q in sel: by.setdefault(q['vendor'],[]).append(q)
 if len(by)<3 or sum(q['carbon'] for q in sel)>d['carbon_cap']: continue
 if any(sum(q['units'] for q in a)>vs[v]['unit_cap'] for v,a in by.items()): continue
 if any(q['needs_same_vendor_sku'] and next(x for x in sel if x['sku']==q['needs_same_vendor_sku'])['vendor']!=q['vendor'] for q in sel): continue
 total=0
 for v,a in by.items():
  r=vs[v]; units=sum(q['units'] for q in a); gross=sum(q['units']*q['unit_cents'] for q in a)
  merch=int((Decimal(gross)*(Decimal(10000-r['tier_bps'])/Decimal(10000))).quantize(Decimal('1'),rounding=ROUND_HALF_UP)) if units>=r['tier_units'] else gross
  cost=merch+(0 if gross>=r['free_shipping_gross'] else r['shipping_cents'])
  if len(set(q['sku'] for q in a))>=2 and merch>=r['rebate_merchandise_min']: cost-=r['rebate_cents']
  total+=cost
 if best is None or total<best: best=total
print(FINAL(str(best)))
